mapper.select:
SELECT u.user_idx, u.user_id, u.user_email, u.password_enabled, u.email_verified, u.email_login_enabled, u.account_status, u.user_role, u.member_grade, u.is_verified_member, u.cash_balance, u.mileage_balance, u.point_balance, u.level_no, u.exp_points, u.total_post_count, u.total_comment_count, u.dormant_at, u.dormant_release_required, u.blocked_until, u.blocked_reason, u.admin_position_code, u.admin_permission_code, u.nickname, u.nationality, u.preferred_lang, u.created_at, u.status_changed_at, IFNULL(s.social_count, 0) AS social_count, s.linked_providers, COALESCE(u.last_login_at, h.last_login_at) AS last_login_at, h.last_login_method, IFNULL(h.login_success_count, 0) AS login_success_count, IFNULL(h.login_fail_count, 0) AS login_fail_count
ORDER BY
IFNULL(s.social_count, 0) ${sortDir}, ( CASE WHEN FIND_IN_SET('KAKAO', IFNULL(s.linked_providers, '')) > 0 THEN 4 ELSE 0 END + CASE WHEN FIND_IN_SET('NAVER', IFNULL(s.linked_providers, '')) > 0 THEN 2 ELSE 0 END + CASE WHEN FIND_IN_SET('GOOGLE', IFNULL(s.linked_providers, '')) > 0 THEN 1 ELSE 0 END ) ${sortDir}
u.user_idx COALESCE(u.last_login_at, h.last_login_at) u.nickname u.user_email u.account_status u.user_role u.member_grade u.level_no IFNULL(h.login_success_count, 0) IFNULL(h.login_fail_count, 0) u.created_at
${sortDir}
, u.user_idx DESC LIMIT #{size} OFFSET #{offset}

SELECT u.user_idx, u.user_id, u.user_email, u.password_enabled, u.email_verified, u.email_login_enabled, u.account_status, u.user_role, u.member_grade, u.is_verified_member, u.cash_balance, u.mileage_balance, u.point_balance, u.level_no, u.exp_points, u.total_post_count, u.total_comment_count, u.dormant_at, u.dormant_release_required, u.blocked_until, u.blocked_reason, u.admin_position_code, u.admin_permission_code, u.nickname, u.nationality, u.preferred_lang, u.created_at, u.status_changed_at, IFNULL(s.social_count, 0) AS social_count, s.linked_providers, COALESCE(u.last_login_at, h.last_login_at) AS last_login_at, h.last_login_method, IFNULL(h.login_success_count, 0) AS login_success_count, IFNULL(h.login_fail_count, 0) AS login_fail_count
ORDER BY
IFNULL(s.social_count, 0) ${sortDir}, ( CASE WHEN FIND_IN_SET('KAKAO', IFNULL(s.linked_providers, '')) > 0 THEN 4 ELSE 0 END + CASE WHEN FIND_IN_SET('NAVER', IFNULL(s.linked_providers, '')) > 0 THEN 2 ELSE 0 END + CASE WHEN FIND_IN_SET('GOOGLE', IFNULL(s.linked_providers, '')) > 0 THEN 1 ELSE 0 END ) ${sortDir}
u.user_idx COALESCE(u.last_login_at, h.last_login_at) u.nickname u.user_email u.account_status u.user_role u.member_grade u.level_no IFNULL(h.login_success_count, 0) IFNULL(h.login_fail_count, 0) u.created_at
${sortDir}
, u.user_idx DESC LIMIT 10000

SELECT u.user_idx, u.user_id, u.user_email, u.password_enabled, u.email_verified, u.email_login_enabled, u.account_status, u.user_role, u.member_grade, u.is_verified_member, u.cash_balance, u.mileage_balance, u.point_balance, u.level_no, u.exp_points, u.total_post_count, u.total_comment_count, u.dormant_at, u.dormant_release_required, u.blocked_until, u.blocked_reason, u.admin_position_code, u.admin_permission_code, u.nickname, u.nationality, u.preferred_lang, u.created_at, u.status_changed_at, IFNULL(s.social_count, 0) AS social_count, s.linked_providers, COALESCE(u.last_login_at, h.last_login_at) AS last_login_at, h.last_login_method, IFNULL(h.login_success_count, 0) AS login_success_count, IFNULL(h.login_fail_count, 0) AS login_fail_count FROM USERS u LEFT JOIN ( SELECT user_idx, COUNT(*) AS social_count, GROUP_CONCAT(provider ORDER BY provider) AS linked_providers FROM USER_SOCIAL GROUP BY user_idx ) s ON u.user_idx = s.user_idx LEFT JOIN ( SELECT user_idx, MAX(login_at) AS last_login_at, SUBSTRING_INDEX(GROUP_CONCAT(login_method ORDER BY login_at DESC), ',', 1) AS last_login_method, SUM(CASE WHEN is_success = 1 THEN 1 ELSE 0 END) AS login_success_count, SUM(CASE WHEN is_success = 0 THEN 1 ELSE 0 END) AS login_fail_count FROM USER_LOGIN_HISTORY WHERE event_type = 'LOGIN' AND auth_type IN ('PASSWORD', 'SOCIAL') GROUP BY user_idx ) h ON u.user_idx = h.user_idx WHERE u.user_idx IN
#{id}
ORDER BY u.created_at DESC

mapper.update:
UPDATE USERS SET account_status = #{status}, status_changed_at = NOW() WHERE user_idx IN
#{idx}
AND user_role NOT IN ('SUPERADMIN', 'SYSTEM')

UPDATE USERS
SET nickname = #{nickname},
    nationality = #{nationality},
    preferred_lang = #{preferredLang}
WHERE user_idx = #{userIdx}

mapper.select:
SELECT COUNT(*)
FROM USERS
WHERE user_idx <> #{userIdx}
  AND user_email = #{email}

SELECT COUNT(*) > 0
FROM ADMIN_EFFECTIVE_PERMISSION_VW
WHERE user_idx = #{userIdx}
  AND permission_code = #{permissionCode}

SELECT *
FROM USER_LOGIN_HISTORY
WHERE user_idx = #{userIdx}
ORDER BY login_at DESC
LIMIT #{limit}

mapper.update:
UPDATE INQUIRY_ANSWER
SET content = #{content}, updated_at = NOW()
WHERE answer_id = #{answerId}

UPDATE INQUIRY_POST
SET status = #{status}, updated_at = NOW()
WHERE inquiry_id = #{inquiryId}

mapper.sql:
FROM USER_LOGIN_HISTORY h LEFT JOIN USERS u ON h.user_idx = u.user_idx
AND h.is_success = TRUE
AND h.is_success = FALSE
AND h.event_type = #{eventType}
AND h.auth_type = #{authType}
AND h.auth_provider = #{authProvider}
AND h.login_method = #{loginMethod}
AND ( h.login_identifier LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.ip_address, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.request_uri, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.fail_reason, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.event_type, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.auth_type, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.auth_provider, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.login_method, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.auth_flow, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.request_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(h.flow_trace_id, '') LIKE CONCAT('%', #{keyword}, '%') )
AND DATE(h.login_at) = #{dateFilter}

mapper.select:
SELECT
    h.login_idx, h.user_idx, u.user_id, u.nickname,
    h.event_type, h.auth_type, h.auth_provider, h.auth_flow,
    h.login_method, h.login_identifier,
    h.session_id, h.request_uri, h.logout_callback_uri,
    h.request_id, h.flow_trace_id,
    h.is_success, h.fail_reason, h.ip_address, h.user_agent, h.login_at

ORDER BY

    h.login_at ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(u.nickname, ''), NULLIF(u.user_id, ''), CAST(h.user_idx AS CHAR), '') ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.event_type, ''), '') ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.auth_type, ''), '') ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.auth_provider, ''), '') ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.auth_flow, ''), NULLIF(h.login_method, ''), '') ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.login_identifier, ''), '') ${sortDir}, h.login_idx ${sortDir}
    h.is_success ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.fail_reason, ''), '') ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.ip_address, ''), '') ${sortDir}, h.login_idx ${sortDir}
    COALESCE(NULLIF(h.request_id, ''), NULLIF(h.flow_trace_id, ''), '') ${sortDir}, h.login_idx ${sortDir}
    h.login_at DESC, h.login_idx DESC

LIMIT #{size} OFFSET #{offset}

mapper.sql:
FROM USER_SECURITY_HISTORY s LEFT JOIN USERS u ON s.user_idx = u.user_idx LEFT JOIN USERS au ON s.actor_user_idx = au.user_idx
AND s.is_success = TRUE
AND s.is_success = FALSE
AND s.event_type = #{eventType}
AND s.event_stage = #{eventStage}
AND ( s.request_id = #{requestKey} OR s.flow_trace_id = #{requestKey} )
AND ( IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(au.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(au.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.input_identifier, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.target_email, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.ip_address, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.request_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.flow_trace_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.event_type, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.event_stage, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.fail_reason, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.detail_message, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(s.user_agent, '') LIKE CONCAT('%', #{keyword}, '%') )
AND DATE(s.occurred_at) = #{dateFilter}

FROM EMAIL_VERIFICATION_REQUEST r
LEFT JOIN USERS u ON r.user_idx = u.user_idx


        AND r.status = #{status}


        AND r.purpose = #{purpose}


        AND (
            IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(r.pending_email, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(r.request_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(r.flow_trace_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(r.ip_address, '') LIKE CONCAT('%', #{keyword}, '%')
        )


        AND DATE(r.requested_at) = #{dateFilter}

FROM EMAIL_VERIFICATION v LEFT JOIN EMAIL_VERIFICATION_REQUEST r ON r.request_id = v.request_id LEFT JOIN USERS u ON v.user_idx = u.user_idx
AND v.used = TRUE
AND v.used = FALSE
AND v.purpose = #{purpose}
AND ( IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(v.email, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(v.request_id, '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(COALESCE(v.flow_trace_id, r.flow_trace_id), '') LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(r.ip_address, '') LIKE CONCAT('%', #{keyword}, '%') )
AND DATE(v.created_at) = #{dateFilter}

FROM USER_ACTIVITY_LOG a
LEFT JOIN USERS u ON a.user_idx = u.user_idx


        AND a.is_success = TRUE


        AND a.is_success = FALSE


        AND a.activity_domain = #{activityDomain}


        AND a.activity_type = #{activityType}


        AND a.activity_provider = #{activityProvider}


        AND a.auth_event_type = #{authEventType}


        AND a.http_method = #{httpMethod}


        AND (
            IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.request_uri, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.request_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.flow_trace_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.activity_code, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.activity_provider, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.target_type, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.target_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(a.ip_address, '') LIKE CONCAT('%', #{keyword}, '%')
        )


        AND DATE(a.created_at) = #{dateFilter}

FROM REPORT r
LEFT JOIN USERS u ON r.user_idx = u.user_idx


        AND r.status = #{status}


        AND r.target_type = #{targetType}


        AND r.reason = #{reason}


        AND (
            IFNULL(u.nickname, '') LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(u.user_id, '') LIKE CONCAT('%', #{keyword}, '%')
            OR CAST(r.target_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%')
            OR IFNULL(r.description, '') LIKE CONCAT('%', #{keyword}, '%')
        )
